     6→  const chunksRef = useRef<Blob[]>([]);
     7→  const streamRef = useRef<MediaStream | null>(null);
     8→  
     9→  const startRecording = useCallback(async () => {
    10→    if (!canvas) {
    11→      alert('Canvas not available');
    12→      return;
    13→    }
    14→    
    15→    try {
    16→      // Capture canvas stream
    17→      const stream = canvas.captureStream(30); // 30 FPS
    18→      streamRef.current = stream;
    19→      
    20→      // Try different mime types for better compatibility
    21→      let mimeType = 'video/webm;codecs=vp9';
    22→      if (!MediaRecorder.isTypeSupported(mimeType)) {
    23→        mimeType = 'video/webm;codecs=vp8';
    24→      }
    25→      if (!MediaRecorder.isTypeSupported(mimeType)) {
    26→        mimeType = 'video/webm';
    27→      }
    28→      
    29→      // Create MediaRecorder
    30→      const mediaRecorder = new MediaRecorder(stream, {
    31→        mimeType,
    32→        videoBitsPerSecond: 2500000, // 2.5 Mbps
    33→      });
    34→      
    35→      chunksRef.current = [];
    36→      mediaRecorder.ondataavailable = (event) => {
    37→        if (event.data.size > 0) {
    38→          chunksRef.current.push(event.data);
    39→        }
    40→      };
    41→      
    42→      mediaRecorder.onstop = () => {
    43→        const blob = new Blob(chunksRef.current, { type: mimeType });
    44→        const url = URL.createObjectURL(blob);
    45→        const a = document.createElement('a');
    46→        a.href = url;
    47→        a.download = `afl-scenario-${Date.now()}.webm`;
    48→        a.click();
    49→        URL.revokeObjectURL(url);
    50→      };
    51→      
    52→      mediaRecorderRef.current = mediaRecorder;
    53→      mediaRecorder.start();
    54→      setIsRecording(true);
    55→    } catch (error) {
    56→      console.error('Error starting recording:', error);
    57→      alert('Failed to start recording. Please check browser compatibility.');
    58→    }
    59→  }, [canvas]);
    60→  
    61→  const stopRecording = useCallback(() => {
    62→    if (mediaRecorderRef.current && isRecording) {
    63→      mediaRecorderRef.current.stop();
    64→      setIsRecording(false);
    65→      
    66→      if (streamRef.current) {
    67→        streamRef.current.getTracks().forEach((track) => track.stop());
    68→        streamRef.current = null;
    69→      }
    70→    }
    71→  }, [isRecording]);
    72→  
    73→  const toggleRecording = useCallback(() => {
    74→    if (isRecording) {
    75→      stopRecording();
    76→    } else {
    77→      startRecording();
    78→    }
    79→  }, [isRecording, startRecording, stopRecording]);
